        if (!object || !positionState) return
        const scrollTarget = positionState.scrollTarget || {}
        const progress = positionState.transformActive
            ? Math.max(0, Math.min(1, positionState.progress ?? 0))
            : 0
        object.position.x += positionState.followX || 0
        object.position.y += positionState.followY || 0
        if (positionState.transformActive) {
            object.position.x += (scrollTarget.offX ?? 0) * progress
            object.position.y += (scrollTarget.offY ?? 0) * progress
            object.position.z += (scrollTarget.offZ ?? 0) * progress
            const scaleMultiplier =
                scrollTarget.scale != null
                    ? 1 + (scrollTarget.scale - 1) * progress
                    : 1
            object.scale.multiplyScalar(scaleMultiplier)
            object.rotation.x +=
                ((scrollTarget.rotX ?? 0) * progress * Math.PI) / 180
            object.rotation.y +=
                ((scrollTarget.rotY ?? 0) * progress * Math.PI) / 180
            object.rotation.z +=
                ((scrollTarget.rotZ ?? 0) * progress * Math.PI) / 180
        }
