const ThreeJSRuntimeRootMemo = React.memo(ThreeJSRuntimeRoot as any)
const ThreeJSRuntimeSlotMemo = React.memo(ThreeJSRuntimeSlot as any)

/**
 * @framerSupportedLayoutWidth any-prefer-fixed
 * @framerSupportedLayoutHeight any-prefer-fixed
 * @framerIntrinsicWidth 800
 * @framerIntrinsicHeight 600
 *
 * @framerDisableUnlink
 */
// @api PublicExport.ThreeJS_Runtime
export default function ThreeJS_Runtime(props: any) {
    const { role = "slot" } = props
    if (role === "root") return <ThreeJSRuntimeRootMemo {...props} />
    return (
        <ThreeJSRuntimeSlotMemo
            {...props}
            asGroup={role === "group" || !!props.asGroup}
        />
    )
}

